-- =====================================================================
-- Migration 0006: carga do conjunto SINTÉTICO de alimentação
-- =====================================================================
-- 277 registros, de 2026-07-01 a 2026-09-28 (90 dias).
--
-- Gerado por analise/gerar_sql_carga.py a partir de
-- analise/dados/feeding_events_sintetico.csv. Não editar à mão.
--
-- ATENÇÃO — ESTES DADOS SÃO SIMULADOS.
-- Toda linha vai com source = 'synthetic'. É essa coluna que faz o
-- aplicativo mostrar o aviso "Dados simulados — em validação técnica".
-- Quando a coleta real começar, os registros do hardware chegam com
-- source = 'device' e o aviso muda sozinho.
--
-- Os eventos já vêm com settled_at preenchido, ou seja, encerrados.
-- Isso é proposital: o gatilho que recalcula consumo só mexe em evento
-- aberto, então a carga não altera os valores do conjunto.
--
-- Pode rodar de novo sem duplicar: os ids são determinísticos e há
-- on conflict do nothing.
-- =====================================================================

on conflict (id) do nothing;

on conflict (id) do nothing;

-- conferência
select count(*) as eventos_sinteticos,
       min(occurred_at)::date as inicio,
       max(occurred_at)::date as fim
  from public.feeding_events where source = 'synthetic';
